% LaTeX macros and settings shared by the pdf and web versions of the blueprint.

% Theorem-like environments that appear in the dependency graph. They share the
% `theorem` counter (the [theorem] argument) and are never reset.
\newtheorem{theorem}{Theorem}
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}

\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}
\newtheorem{convention}[theorem]{Convention}

% Mathematical operators and macros used in the chapters. KaTeX (dashboard) and
% plasTeX (web) only know standard LaTeX/AMS, so non-standard commands are defined here.
\DeclareMathOperator{\Spec}{Spec}
\DeclareMathOperator{\Pic}{Pic}
\DeclareMathOperator{\Hom}{Hom}
\DeclareMathOperator{\Mor}{Mor}
\DeclareMathOperator{\Div}{Div}
\DeclareMathOperator{\Alb}{Alb}
\DeclareMathOperator{\Sym}{Sym}
\DeclareMathOperator{\genus}{genus}
\DeclareMathOperator{\finrank}{finrank}
\DeclareMathOperator{\id}{id}
\DeclareMathOperator{\Ext}{Ext}
\DeclareMathOperator{\Proj}{Proj}
\DeclareMathOperator{\Frac}{Frac}
\DeclareMathOperator{\coker}{coker}
\newcommand{\Jac}{\mathrm{Jac}}
\newcommand{\struct}[1]{\mathcal{O}_{#1}}
\newcommand{\Over}{\mathrm{Over}}
\newcommand{\GrpObj}{\mathrm{GrpObj}}

% Visible source-alignment markers for mathematical statements.
\newcommand{\provenancetag}[1]{%
  \par\smallskip\noindent\textbf{\textsc{#1}.}\enspace\ignorespaces}
\newcommand{\alignmentcheck}[1]{%
  \par\noindent\textbf{#1}\enspace\ignorespaces}

% Blackboard-bold and script fallbacks.
\providecommand{\OO}{\mathcal{O}}
\providecommand{\F}{\mathcal{F}}
\providecommand{\PP}{\mathbb{P}}
\providecommand{\N}{\mathbb{N}}
\providecommand{\Z}{\mathbb{Z}}
\providecommand{\Q}{\mathbb{Q}}
\providecommand{\op}{\mathrm{op}}

% plasTeX does not load cleveref; fall back to \ref so cross-references resolve on
% the web output. On pdflatex the real \cref (loaded later) takes precedence.
\providecommand{\cref}[1]{\ref{#1}}
\providecommand{\Cref}[1]{\ref{#1}}

